package com.lmspilot.integration.api;import com.lmspilot.contracts.Permissions;import jakarta.validation.Valid;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/integrations") @PreAuthorize("hasAuthority('"+Permissions.INTEGRATIONS_MANAGE+"')") public class IntegrationController{private final IntegrationAdapterService service;public IntegrationController(IntegrationAdapterService s){service=s;}@GetMapping public List<AdapterResponse> list(){return service.list();}@PostMapping public AdapterResponse create(@Valid @RequestBody AdapterRequest in){return service.save(null,in);}@PutMapping("/{id}")public AdapterResponse update(@PathVariable UUID id,@Valid @RequestBody AdapterRequest in){return service.save(id,in);}@PostMapping("/{id}/test")public AdapterResponse test(@PathVariable UUID id){return service.test(id);}}
